func TestDurableDataConcurrentCASHasOneWinner(t *testing.T) {
	forEachDurableDataStore(t, func(t *testing.T, selected durableDataSelectedStore, _ *sql.DB) {
		ctx := context.Background()
		catalog, ref := durableDataTestCatalog(t)
		if err := registerDurableDataTestCatalog(ctx, selected, catalog); err != nil {
			t.Fatal(err)
		}
		const contenders = 12
		results := make(chan string, contenders)
		errs := make(chan error, contenders)
		var wg sync.WaitGroup
		for index := 0; index < contenders; index++ {
			wg.Add(1)
			go func(index int) {
				defer wg.Done()
				result, err := selected.ExecuteDataSourceOperation(ctx, durabledata.SourceCommand{Operation: "import", SourceInvocationID: uuid.NewString(), Actor: fmt.Sprintf("actor-%d", index), BundleHash: testDataBundle, Declaration: ref, ExpectedHead: durabledata.AbsentHead(), InputFormat: "jsonl", Input: []byte(fmt.Sprintf("{\"slug\":\"row-%02d\",\"score\":%d}\n", index, index))})
				if err != nil {
					errs <- err
					return
				}
				results <- result.Outcome
			}(index)
		}
		wg.Wait()
		close(results)
		close(errs)
		for err := range errs {
			t.Fatalf("concurrent import: %v", err)
		}
		counts := map[string]int{}
		for outcome := range results {
			counts[outcome]++
		}
		if counts["accepted"] != 1 || counts["head_conflict"] != contenders-1 {
			t.Fatalf("concurrent outcomes = %#v", counts)
		}
	})
}

