		if err != nil || replay.Candidate.VersionID != first.Candidate.VersionID || replay.CompletedAt != first.CompletedAt {
			t.Fatalf("reconstructed exact replay = %#v, %v; want %#v", replay, err, first)
		}
		requireEmptySourceDefectsPage(t, replay)
		if _, err := primary.ExecuteDataSourceOperation(ctx, durabledata.SourceCommand{Operation: "check", SourceInvocationID: firstID, Actor: "operator", BundleHash: testDataBundle, Declaration: ref, ExpectedHead: first.Head.After, InputFormat: "jsonl", Input: []byte("{\"slug\":\"different\",\"score\":3}\n")}); err == nil {
			t.Fatal("conflicting source_invocation_id reuse succeeded")
		}
		canonicalReorder, err := primary.ExecuteDataSourceOperation(ctx, durabledata.SourceCommand{Operation: "check", SourceInvocationID: uuid.NewString(), Actor: "operator", BundleHash: testDataBundle, Declaration: ref, ExpectedHead: first.Head.After, InputFormat: "jsonl", Input: []byte("{\"score\":1,\"slug\":\"alpha\"}\n{\"score\":2,\"slug\":\"beta\"}\n")})
		if err != nil || canonicalReorder.Outcome != "accepted" || canonicalReorder.Candidate.State != "candidate" || canonicalReorder.Candidate.Alias != "" || canonicalReorder.Candidate.VersionID != first.Candidate.VersionID {
			t.Fatalf("canonical reorder = %#v, %v", canonicalReorder, err)
		}
		rejected, err := primary.ExecuteDataSourceOperation(ctx, durabledata.SourceCommand{Operation: "import", SourceInvocationID: uuid.NewString(), Actor: "operator", BundleHash: testDataBundle, Declaration: ref, ExpectedHead: first.Head.After, InputFormat: "jsonl", Input: []byte("{}\n{\"slug\":\"wrong\",\"score\":\"wrong\"}\n{\"slug\":\"alpha\",\"score\":4}\n{\"slug\":\"alpha\",\"score\":5}\n")})
		if err != nil || rejected.Outcome != "validation_rejected" || rejected.Head.Changed || len(rejected.Defects.Items) != 3 {
			t.Fatalf("whole-input rejection = %#v, %v", rejected, err)
		}
		second, err := primary.ExecuteDataSourceOperation(ctx, durabledata.SourceCommand{Operation: "import", SourceInvocationID: uuid.NewString(), Actor: "operator", BundleHash: testDataBundle, Declaration: ref, ExpectedHead: first.Head.After, InputFormat: "jsonl", Input: []byte("{\"slug\":\"alpha\",\"score\":9}\n")})
