		if summary.Declaration != ref || summary.LocalName != catalog.Declarations[0].Name || summary.SchemaDigest != catalog.Declarations[0].SchemaDigest || !summary.Head.Equal(second.Head.After) || summary.VersionCount != 2 || summary.MaterializedVersionCount != 1 || summary.MaterializedBytes != len(snapshot.Versions[1].CanonicalJSONL) {
			t.Fatalf("bounded declaration summary = %#v", summary)
		}
