				t.Fatal(err)
			}
			record, err := selected.LoadDataSourceOperation(ctx, id)
			if err != nil {
				t.Fatal(err)
			}
			schema := []byte(`{"type":"object","additionalProperties":false,"required":["score"],"properties":{"score":{"type":"integer"}}}`)
			record.Evaluation.Declaration = durabledata.Declaration{Name: ref.EventName, Ref: ref, OwnerFlowID: "root", SchemaDigest: durabledata.SchemaDigestFor(schema), CanonicalSchema: schema}
			_, result, evidence, err := record.Evaluation.Evaluate(command)
			if err != nil || result.Outcome != "accepted" {
				t.Fatalf("hostile source context = %#v, %v", result, err)
			}
			updateSourceReceiptAggregate(t, ctx, selected, db, id, record.Evaluation, result, evidence)
			assertIntegrity(t, id, command)
		})
		first, err := selected.ExecuteDataSourceOperation(ctx, durabledata.SourceCommand{Operation: "import", SourceInvocationID: uuid.NewString(), Actor: "operator", BundleHash: testDataBundle, Declaration: ref, ExpectedHead: durabledata.AbsentHead(), InputFormat: "jsonl", Input: []byte("{\"slug\":\"base\",\"score\":1}\n")})
		if err != nil {
			t.Fatal(err)
		}
		t.Run("coordinated historical head replacement", func(t *testing.T) {
			id := uuid.NewString()
			command := durabledata.SourceCommand{Operation: "check", SourceInvocationID: id, Actor: "operator", BundleHash: testDataBundle, Declaration: ref, ExpectedHead: first.Head.After, InputFormat: "jsonl", Input: []byte("{\"slug\":\"next\",\"score\":2}\n")}
			if _, err := selected.ExecuteDataSourceOperation(ctx, command); err != nil {
				t.Fatal(err)
			}
			record, err := selected.LoadDataSourceOperation(ctx, id)
			if err != nil {
				t.Fatal(err)
			}
			record.Evaluation.Base = durabledata.SourceEvaluationBase{State: "absent", Head: durabledata.HeadResult{Before: durabledata.AbsentHead(), After: durabledata.AbsentHead()}}
			_, result, evidence, err := record.Evaluation.Evaluate(command)
			if err != nil || result.Outcome != "head_conflict" {
				t.Fatalf("hostile historical context = %#v, %v", result, err)
			}
			updateSourceReceiptAggregate(t, ctx, selected, db, id, record.Evaluation, result, evidence)
			assertIntegrity(t, id, command)
		})
	})
}

