func TestResolveDataVersionPayloadIsAtomicAcrossPruneAndRematerialize(t *testing.T) {
	forEachDurableDataStore(t, func(t *testing.T, selected durableDataSelectedStore, _ *sql.DB) {
		ctx := context.Background()
		catalog, ref := durableDataTestCatalog(t)
		if err := registerDurableDataTestCatalog(ctx, selected, catalog); err != nil {
			t.Fatalf("register durable data test catalog: %v", err)
		}
		firstInput := []byte("{\"slug\":\"alpha\",\"score\":1}\n")
		secondInput := []byte("{\"slug\":\"beta\",\"score\":2}\n")
		first, err := selected.ExecuteDataSourceOperation(ctx, durabledata.SourceCommand{Operation: "import", SourceInvocationID: uuid.NewString(), Actor: "operator", BundleHash: testDataBundle, Declaration: ref, ExpectedHead: durabledata.AbsentHead(), InputFormat: "jsonl", Input: firstInput})
		if err != nil || first.Outcome != "accepted" {
			t.Fatalf("first import = %#v, %v", first, err)
		}
		second, err := selected.ExecuteDataSourceOperation(ctx, durabledata.SourceCommand{Operation: "import", SourceInvocationID: uuid.NewString(), Actor: "operator", BundleHash: testDataBundle, Declaration: ref, ExpectedHead: first.Head.After, InputFormat: "jsonl", Input: secondInput})
		if err != nil || second.Outcome != "accepted" {
			t.Fatalf("second import = %#v, %v", second, err)
		}
		writerErr := make(chan error, 1)
		done := make(chan struct{})
		go func() {
			defer close(done)
			for cycle := 0; cycle < 12; cycle++ {
				pruned, err := selected.PruneDataResource(ctx, durabledata.PruneCommand{PruneInvocationID: uuid.NewString(), Actor: "operator", Declaration: ref, VersionID: first.Candidate.VersionID, ExpectedHead: second.Head.After})
				if err != nil || pruned.Outcome != "pruned" {
					writerErr <- fmt.Errorf("cycle %d prune = %#v: %w", cycle, pruned, err)
					return
				}
				rematerialized, err := selected.ExecuteDataSourceOperation(ctx, durabledata.SourceCommand{Operation: "import", SourceInvocationID: uuid.NewString(), Actor: "operator", BundleHash: testDataBundle, Declaration: ref, ExpectedHead: second.Head.After, InputFormat: "jsonl", Input: firstInput})
				if err != nil || rematerialized.Outcome != "accepted" || rematerialized.Candidate.VersionID != first.Candidate.VersionID {
					writerErr <- fmt.Errorf("cycle %d rematerialize = %#v: %w", cycle, rematerialized, err)
					return
				}
				restoredHead, err := selected.ExecuteDataSourceOperation(ctx, durabledata.SourceCommand{Operation: "import", SourceInvocationID: uuid.NewString(), Actor: "operator", BundleHash: testDataBundle, Declaration: ref, ExpectedHead: rematerialized.Head.After, InputFormat: "jsonl", Input: secondInput})
				if err != nil || restoredHead.Outcome != "accepted" || restoredHead.Candidate.VersionID != second.Candidate.VersionID {
					writerErr <- fmt.Errorf("cycle %d restore head = %#v: %w", cycle, restoredHead, err)
					return
				}
			}
			writerErr <- nil
		}()
		selector := durabledata.VersionSelector{Kind: "version", VersionID: first.Candidate.VersionID}
		observations := 0
		var readerErr error
	readLoop:
		for {
			select {
			case <-done:
				break readLoop
			default:
			}
			summary, version, err := selected.ResolveDataVersionPayload(ctx, ref, selector)
			if err != nil {
				readerErr = fmt.Errorf("atomic payload resolution: %w", err)
				<-done
				break readLoop
			}
			if err := summary.ValidateVersion(version); err != nil {
				readerErr = fmt.Errorf("non-atomic summary/payload pair: %#v / %#v: %w", summary, version, err)
				<-done
				break readLoop
			}
			observations++
		}
		if err := <-writerErr; err != nil {
			t.Fatal(err)
		}
		if readerErr != nil {
			t.Fatal(readerErr)
		}
		if observations == 0 {
			summary, version, err := selected.ResolveDataVersionPayload(ctx, ref, selector)
			if err != nil || summary.ValidateVersion(version) != nil {
				t.Fatalf("final atomic payload resolution = %#v / %#v: %v", summary, version, err)
			}
		}
	})
}

