			t.Run(tc.name, func(t *testing.T) {
				runID, sourceID, key := uuid.NewString(), uuid.NewString(), uuid.NewString()
				ref := scanRef
				if tc.rowCount == 0 {
					ref = scoreRef
				}
				data := map[string]any{"imports": []any{dataRunFusedImport(sourceID, ref, durabledata.AbsentHead(), []byte(tc.rows))}, "pins": []any{}}
