			}
			if got := dataRunObservedCount(t, fixture, storetest.CountRunFanOutIntentStorage, runID); got != 2 {
				t.Fatalf("multi-pin intents = %d, want 2", got)
			}
			if got := dataRunObservedCount(t, fixture, storetest.CountPhysicalRunEvents, runID); got != 0 {
				t.Fatalf("multi-pin run created %d initial events", got)
			}
		})
		t.Run("one invalid pin rejects the whole run", func(t *testing.T) {
			runID := uuid.NewString()
			data := map[string]any{"imports": []any{}, "pins": []any{map[string]any{"declaration": dataRunDeclaration(scanRef), "version_id": versions[scanRef.Key()]}, map[string]any{"declaration": dataRunDeclaration(scoreRef), "version_id": "resource-version-v1:sha256:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}}}
