				count func(context.Context, any, string) (int, error)
			}{{"runs", storetest.CountPhysicalRunIdentity}, {"events", storetest.CountPhysicalRunEvents}, {"resource_version_pins", storetest.CountRunResourcePinsStorage}, {"fan_out_intents", storetest.CountRunFanOutIntentStorage}} {
