					t.Fatalf("invalid second pin left %d %s rows", got, observed.table)
				}
			}
			receipt, err := fixture.reconstructed.LoadDataRunCreationOperation(ctx, runID)
			if err != nil || receipt.Summary.Outcome != "data_rejected" || receipt.Summary.PinCount != 0 || receipt.Summary.Rejection.Code != durabledata.RunCreationRejectionVersionMissing {
				t.Fatalf("invalid second pin receipt = %#v, %v", receipt, err)
			}
			replay := rpcCall(t, handler, body)
			if replay.Error == nil || !reflect.DeepEqual(replay.Error, response.Error) || dataRunObservedCount(t, fixture, storetest.CountRunDataCreationOperationsStorage, runID) != 1 {
