				if err != nil || !reflect.DeepEqual(before.Head, after.Head) || len(before.Versions) != len(after.Versions) {
					t.Fatalf("failed admission changed resource: before=%#v after=%#v err=%v", before, after, err)
				}
			})
		}
		for _, eventBacked := range []bool{false, true} {
			mode := "feed-only"
			if eventBacked {
				mode = "event-plus-feed"
			}
			sourceID := uuid.NewString()
			data := map[string]any{"imports": []any{dataRunFusedImport(sourceID, openedRef, durabledata.AbsentHead(), []byte("{\"topic\":\"probe\"}\n"))}, "pins": []any{}}
			assertRejected(mode+" import", eventBacked, data, sourceID)
		}
		imported, err := fixture.primary.ExecuteDataSourceOperation(ctx, durabledata.SourceCommand{Operation: "import", SourceInvocationID: uuid.NewString(), Actor: "operator", BundleHash: bundleHash, Declaration: openedRef, ExpectedHead: durabledata.AbsentHead(), InputFormat: "jsonl", Input: []byte("{\"topic\":\"pinned\"}\n")})
		if err != nil || imported.Outcome != "accepted" {
			t.Fatalf("prepare non-output-pinned resource: %#v, %v", imported, err)
		}
		for _, eventBacked := range []bool{false, true} {
			mode := "feed-only"
			if eventBacked {
				mode = "event-plus-feed"
			}
			data := map[string]any{"imports": []any{}, "pins": []any{map[string]any{"declaration": dataRunDeclaration(openedRef), "version_id": imported.Candidate.VersionID}}}
			assertRejected(mode+" pin", eventBacked, data, "")
		}
	})
}

